// The `module.constructor` route for #181, which needs an ordinary CommonJS module to exist in:
// inside a CJS wrapper `module` is the module record, and `module.constructor` IS `node:module`'s
// export — the `Module` class — with no `require("node:module")` for a shim to intercept. Every
// CJS file in every dependency has it for free, which is why the gate cannot live on the shim.
//
// Inert per AGENTS.md § 8: this file hands back a class reference and does nothing with it.
exports.moduleConstructor = () => module.constructor;
